impl<R: Read> CsvStream<R> {
    pub fn new(inner: R) -> Self {
        Self {
            inner,
            buf: vec![0u8; CHUNK].into_boxed_slice(),
            pos: 0,
            len: 0,
            record: Vec::with_capacity(256),
        }
    }

