const MAX_RECORD_BYTES: usize = 64 * 1024 * 1024;

/// Lee un CSV en streaming y devuelve el promedio de la columna `column`
/// (índice base 0). `has_header` indica si hay que saltear la primera fila.
///
/// Memoria: O(1) respecto de la cantidad de filas (buffer de 1 MiB + un registro).
/// Devuelve `Ok(None)` si no hay filas de datos o si todas las celdas de la
/// columna están vacías.
pub fn mean_of_csv_column<R: Read>(
    input: R,
    column: usize,
    has_header: bool,
) -> io::Result<Option<f64>> {
    let mut reader = BufReader::with_capacity(1 << 20, input);
    let mut record = Vec::with_capacity(1024);
    let mut scratch = Vec::with_capacity(1024);

    let mut mean = 0.0f64;
    let mut count: u64 = 0;
    let mut row: u64 = 0;

    if has_header {
        if !read_record(&mut reader, &mut record, &mut scratch)? {
            return Ok(None);
        }
        if field_slice(&record, column).is_none() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!("la cabecera no tiene la columna índice {column}"),
            ));
        }
    }

    while read_record(&mut reader, &mut record, &mut scratch)? {
        if record.is_empty() {
            continue; // línea en blanco: se ignora
        }
        row += 1;

        let raw = field_slice(&record, column).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("la fila de datos {row} no tiene la columna índice {column}"),
            )
        })?;

        let value = match parse_number(raw).map_err(|msg| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("fila de datos {row}, columna {column}: {msg}"),
            )
        })? {
            Some(v) => v,
            None => continue, // celda vacía: se cuenta como faltante
        };

        count += 1;
        // Media incremental: no acumula una suma que pueda desbordar y evita
        // la pérdida de precisión de sumar valores de magnitud muy dispar.
        mean += (value - mean) / count as f64;
    }

    if count == 0 {
        Ok(None)
    } else {
        Ok(Some(mean))
    }
}

