    SOCKET        sock;
    HANDLE        pipe_in;   /* write end hacia stdin del hijo */
    HANDLE        pipe_out;  /* read end desde stdout/stderr del hijo */
    HANDLE        done;      /* señal compartida de parada */
    volatile LONG refs;
} relay_t;

static void relay_release(relay_t* r) {
    if (InterlockedDecrement(&r->refs) == 0) {
        HeapFree(GetProcessHeap(), 0, r);
    }
