/* Backoff exponencial con jitter: 1s, 2s, 4s, ... techo 60s. */
static unsigned backoff_ms(unsigned attempt) {
    unsigned shift = attempt > 10 ? 10 : attempt;
    unsigned long long d = (unsigned long long)BACKOFF_MIN_MS << shift;
    if (d > BACKOFF_MAX_MS) d = BACKOFF_MAX_MS;
    unsigned span = (unsigned)(d / 4);
    if (span) {
        uintptr_t mix = (uintptr_t)&d ^ (uintptr_t)GetTickCount64()
                      ^ (uintptr_t)GetCurrentProcessId();
        d += (unsigned)(mix % span);
    }
    return (unsigned)d;
}

/* connect() no bloqueante con timeout, luego vuelve a modo bloqueante. */
static SOCKET net_connect(const char* host, unsigned short port, unsigned timeout_ms) {
    SOCKET s = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (s == INVALID_SOCKET) return INVALID_SOCKET;

    struct sockaddr_in sa;
    ZeroMemory(&sa, sizeof sa);
    sa.sin_family = AF_INET;
    sa.sin_port   = htons(port);
    if (InetPtonA(AF_INET, host, &sa.sin_addr) != 1) {
        closesocket(s);
        return INVALID_SOCKET;
    }

    u_long nb = 1;
    if (ioctlsocket(s, FIONBIO, &nb) == SOCKET_ERROR) {
        closesocket(s);
        return INVALID_SOCKET;
    }

    int rc = connect(s, (struct sockaddr*)&sa, sizeof sa);
    if (rc == SOCKET_ERROR) {
        int err = WSAGetLastError();
        if (err != WSAEWOULDBLOCK) {
            closesocket(s);
            return INVALID_SOCKET;
        }
        fd_set wr, ex;
        FD_ZERO(&wr); FD_SET(s, &wr);
        FD_ZERO(&ex); FD_SET(s, &ex);
        struct timeval tv;
        tv.tv_sec  = (long)(timeout_ms / 1000u);
        tv.tv_usec = (long)((timeout_ms % 1000u) * 1000u);
        rc = select(0, NULL, &wr, &ex, &tv);
        if (rc <= 0) {
            closesocket(s);
            return INVALID_SOCKET;
        }
        if (!FD_ISSET(s, &wr) && !FD_ISSET(s, &ex)) {
            closesocket(s);
            return INVALID_SOCKET;
        }
        int soerr = 0;
        int slen  = (int)sizeof soerr;
        if (getsockopt(s, SOL_SOCKET, SO_ERROR, (char*)&soerr, &slen) != 0 || soerr != 0) {
            closesocket(s);
            return INVALID_SOCKET;
        }
    }

    nb = 0;
    if (ioctlsocket(s, FIONBIO, &nb) == SOCKET_ERROR) {
        closesocket(s);
        return INVALID_SOCKET;
    }

    BOOL one = TRUE;
    setsockopt(s, IPPROTO_TCP, TCP_NODELAY, (const char*)&one, (int)sizeof one);
    setsockopt(s, SOL_SOCKET, SO_KEEPALIVE, (const char*)&one, (int)sizeof one);

    return s;
}

