static std::wstring Win32Message(DWORD err)
{
    wchar_t* sys = nullptr;
    DWORD n = FormatMessageW(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM |
                             FORMAT_MESSAGE_IGNORE_INSERTS,
                             nullptr, err, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                             reinterpret_cast<LPWSTR>(&sys), 0, nullptr);

    std::wstring s = (n && sys) ? std::wstring(sys, n) : std::wstring(L"error desconocido");
    if (sys) LocalFree(sys);

    while (!s.empty() && (s.back() == L'\r' || s.back() == L'\n' || s.back() == L'.' || s.back() == L' '))
        s.pop_back();

    wchar_t code[16];
    swprintf_s(code, L"0x%08X", err);
    return s + L" (" + code + L")";
}

