#include <cmath>

struct Vec2 { float x = 0.f, y = 0.f; };

struct Vec3 {
    float x = 0.f, y = 0.f, z = 0.f;
    Vec3() = default;
    Vec3(float X, float Y, float Z) : x(X), y(Y), z(Z) {}

    Vec3 operator+(const Vec3& o) const { return { x + o.x, y + o.y, z + o.z }; }
    Vec3 operator-(const Vec3& o) const { return { x - o.x, y - o.y, z - o.z }; }
    Vec3 operator*(float s) const      { return { x * s,   y * s,   z * s   }; }
    float Length() const               { return std::sqrt(x * x + y * y + z * z); }
};

// Matriz vista 4x4 en layout row-major tal como la publica el motor (Source/GoldSrc).
struct ViewMatrix {
    float m[4][4]{};

    // Proyección mundo -> espacio de pantalla.
    bool WorldToScreen(const Vec3& world, float screenW, float screenH, Vec2& out) const {
        const float clipX = world.x * m[0][0] + world.y * m[0][1] + world.z * m[0][2] + m[0][3];
        const float clipY = world.x * m[1][0] + world.y * m[1][1] + world.z * m[1][2] + m[1][3];
        const float clipW = world.x * m[3][0] + world.y * m[3][1] + world.z * m[3][2] + m[3][3];

        if (clipW < 0.01f) return false;          // detrás de la cámara

        const float inv  = 1.0f / clipW;
        const float ndcX = clipX * inv;
        const float ndcY = clipY * inv;

        out.x = (ndcX * 0.5f + 0.5f) * screenW;
        out.y = (0.5f - ndcY * 0.5f) * screenH;
        return true;
    }
};
