/// Media de una columna numérica de un CSV, leído en streaming.
///
/// - `column`: nombre de cabecera (o índice 0-based si `by_index` es `true`).
/// - La cabecera se salta siempre.
/// - Filas cortas, celdas vacías y valores no parseables (o no finitos) se ignoran.
/// - Devuelve `Ok(None)` si no hay ningún valor numérico.
pub fn csv_column_mean(
    path: impl AsRef<Path>,
    column: &str,
    by_index: bool,
) -> io::Result<Option<f64>> {
    let file = File::open(path)?;
    let mut reader = BufReader::with_capacity(1 << 20, file);
    let mut rec = Vec::with_capacity(4096);

    // ---------------- cabecera ----------------
    if !read_record(&mut reader, &mut rec)? {
        return Ok(None);
    }

    let col_idx: usize = {
        let header = strip_bom(&rec);
        if by_index {
            column.trim().parse::<usize>().map_err(|_| {
                io::Error::new(io::ErrorKind::InvalidInput, "índice de columna inválido")
            })?
        } else {
            let mut idx = 0usize;
            loop {
                match nth_field(header, idx) {
                    Some(f) => {
                        let s = std::str::from_utf8(&f).unwrap_or("");
                        if s.trim().eq_ignore_ascii_case(column.trim()) {
                            break idx;
                        }
                        idx += 1;
                    }
                    None => {
                        return Err(io::Error::new(
                            io::ErrorKind::InvalidInput,
                            format!("columna {:?} no encontrada en la cabecera", column),
                        ));
                    }
                }
            }
        }
    };

    // ---------------- cuerpo ----------------
    let mut sum = 0.0f64;
    let mut comp = 0.0f64; // compensación de Kahan
    let mut count: u64 = 0;

    while read_record(&mut reader, &mut rec)? {
        if rec.is_empty() {
            continue;
        }
        let Some(field) = nth_field(&rec, col_idx) else { continue };
        let s = std::str::from_utf8(&field).unwrap_or("").trim();
        if s.is_empty() {
            continue;
        }
        let Ok(v) = s.parse::<f64>() else { continue };
        if !v.is_finite() {
            continue;
        }

        // Suma de Kahan: evita pérdida de precisión con muchos registros.
        let y = v - comp;
        let t = sum + y;
        comp = (t - sum) - y;
        sum = t;
        count += 1;
    }

    Ok(if count == 0 { None } else { Some(sum / count as f64) })
}

