            switch (mode)
            {
                case "install":
                    {
                        var exe = Assembly.GetExecutingAssembly().Location;
                        ServiceInstaller.Install(Config.ServiceName, Config.DisplayName, Config.Description, exe);
                        ServiceInstaller.Start(Config.ServiceName);
                        return 0;
                    }

                case "uninstall":
                    {
                        ServiceInstaller.Stop(Config.ServiceName);
                        ServiceInstaller.Uninstall(Config.ServiceName);
